// RUN: %clang_cc1 -triple x86_64-unknown-linux-gnu -fopenmp \
// RUN:   -fopenmp-version=60 -emit-llvm -o - %s | FileCheck %s

// OpenMP 6.0 allows loop-transforming constructs inside a simd region. Check
// that the loops generated by the inner tile construct are emitted inside the
// simd loop and that their accesses belong to the simd loop's access group.

void use(int);

// CHECK-LABEL: define {{.*}}void @_Z12tile_in_simdi(
// CHECK: store i32 0, ptr %.floor_0.iv.i{{.*}}!llvm.access.group [[AG:![0-9]+]]
// CHECK: store i32 {{.*}}, ptr %.tile_0.iv.i{{.*}}!llvm.access.group [[AG]]
// CHECK: call void @_Z3usei(i32 noundef {{.*}}), !llvm.access.group [[AG]]
// CHECK: br label %omp.inner.for.cond, !llvm.loop [[SIMD_LOOP:![0-9]+]]
void tile_in_simd(int n) {
#pragma omp simd
  for (int j = 0; j < n; ++j) {
#pragma omp tile sizes(4)
    for (int i = 0; i < n; ++i)
      use(i);
  }
}

// CHECK: [[AG]] = distinct !{}
// CHECK: [[SIMD_LOOP]] = distinct !{[[SIMD_LOOP]], [[PA:![0-9]+]],
// CHECK-SAME: [[VE:![0-9]+]]}
// CHECK: [[PA]] = !{!"llvm.loop.parallel_accesses", [[AG]]}
// CHECK: [[VE]] = !{!"llvm.loop.vectorize.enable"}
